{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.new_repeat_dashboard_mom AS WITH online_raw AS ( SELECT UPPER(TRIM(f.CATEGORY)) AS RAW_CATEGORY, \'Online\' AS CHANNEL, f.CUSTOMER_ID, TO_DATE(f.ORDER_TIMESTAMP) AS ORDER_DATE, CASE WHEN f.NEW_CUSTOMER_FLAG IN ( \'New\', \'Yet to make completed order\' ) THEN \'New\' WHEN f.NEW_CUSTOMER_FLAG = \'Repeated\' THEN \'Repeat\' ELSE NULL END AS CUSTOMER_TYPE FROM snitch_db.maplemonk.fact_items_snitch f WHERE f.CUSTOMER_ID IS NOT NULL AND f.CATEGORY IS NOT NULL AND f.ORDER_TIMESTAMP IS NOT NULL ), offline_raw AS ( SELECT UPPER(TRIM(f.CATEGORY)) AS RAW_CATEGORY, \'Offline\' AS CHANNEL, RIGHT( REGEXP_REPLACE(f.PHONE, \'[^0-9]\', \'\'), 10 ) AS CUSTOMER_ID, TO_DATE(f.ORDER_DATE) AS ORDER_DATE, CASE WHEN a.PHONE_NO IS NULL THEN NULL WHEN CAST(a.FIRST_ORDER_DATE AS DATE) = CAST(f.ORDER_DATE AS DATE) THEN \'New\' ELSE \'Repeat\' END AS CUSTOMER_TYPE FROM snitch_db.maplemonk.store_fact_items_offline f LEFT JOIN snitch_db.maplemonk.customer_acq_date_channel a ON RIGHT( REGEXP_REPLACE(f.PHONE, \'[^0-9]\', \'\'), 10 ) = RIGHT( REGEXP_REPLACE(a.PHONE_NO, \'[^0-9]\', \'\'), 10 ) WHERE f.PHONE IS NOT NULL AND f.CATEGORY IS NOT NULL AND f.ORDER_DATE IS NOT NULL ), customer_raw AS ( SELECT RAW_CATEGORY, CHANNEL, CUSTOMER_ID, ORDER_DATE, CUSTOMER_TYPE FROM online_raw UNION ALL SELECT RAW_CATEGORY, CHANNEL, CUSTOMER_ID, ORDER_DATE, CUSTOMER_TYPE FROM offline_raw ), category_cleaned AS ( SELECT CASE WHEN RAW_CATEGORY IN (\'SHIRT\', \'SHIRTS\') THEN \'SHIRT\' WHEN RAW_CATEGORY IN ( \'T-SHIRT\', \'T-SHIRTS\', \'TSHIRT\', \'TSHIRTS\' ) THEN \'T-SHIRT\' WHEN RAW_CATEGORY IN (\'TROUSER\', \'TROUSERS\') THEN \'TROUSER\' WHEN RAW_CATEGORY IN (\'JOGGER\', \'JOGGERS\') THEN \'JOGGER\' WHEN RAW_CATEGORY IN (\'CARGO\', \'CARGOS\') THEN \'CARGO\' WHEN RAW_CATEGORY IN (\'DENIM\', \'DENIMS\') THEN \'DENIM\' WHEN RAW_CATEGORY IN (\'OVERSHIRT\', \'OVERSHIRTS\') THEN \'OVERSHIRT\' WHEN RAW_CATEGORY IN ( \'TRACKPANT\', \'TRACKPANTS\', \'TRACK PANT\', \'TRACK PANTS\' ) THEN \'TRACKPANT\' WHEN RAW_CATEGORY IN (\'PYJAMA\', \'PYJAMAS\') THEN \'PYJAMA\' WHEN RAW_CATEGORY IN (\'PERFUME\', \'PERFUMES\') THEN \'PERFUME\' WHEN RAW_CATEGORY IN (\'SUNGLASS\', \'SUNGLASSES\') THEN \'SUNGLASSES\' WHEN RAW_CATEGORY = \'SHOES\' THEN \'SHOES\' ELSE RAW_CATEGORY END AS CATEGORY, CHANNEL, CUSTOMER_ID, ORDER_DATE, CUSTOMER_TYPE FROM customer_raw ), customer_base AS ( SELECT DATE_TRUNC(\'MONTH\', ORDER_DATE) AS ORDER_MONTH_DATE, CATEGORY, CHANNEL, CUSTOMER_ID, CASE WHEN MAX( CASE WHEN CUSTOMER_TYPE = \'Repeat\' THEN 1 ELSE 0 END ) = 1 THEN \'Repeat\' WHEN MAX( CASE WHEN CUSTOMER_TYPE = \'New\' THEN 1 ELSE 0 END ) = 1 THEN \'New\' ELSE NULL END AS CUSTOMER_TYPE FROM category_cleaned WHERE CUSTOMER_TYPE IS NOT NULL GROUP BY DATE_TRUNC(\'MONTH\', ORDER_DATE), CATEGORY, CHANNEL, CUSTOMER_ID ), channel_customer_classification AS ( SELECT ORDER_MONTH_DATE, CHANNEL, CUSTOMER_ID, CASE WHEN MAX( CASE WHEN CUSTOMER_TYPE = \'Repeat\' THEN 1 ELSE 0 END ) = 1 THEN \'Repeat\' ELSE \'New\' END AS CUSTOMER_TYPE FROM customer_base GROUP BY ORDER_MONTH_DATE, CHANNEL, CUSTOMER_ID ), channel_level AS ( SELECT ORDER_MONTH_DATE, \'CHANNEL_LEVEL\' AS ANALYSIS_LEVEL, \'ALL\' AS CATEGORY, CHANNEL, COUNT( DISTINCT CASE WHEN CUSTOMER_TYPE = \'New\' THEN CUSTOMER_ID END ) AS NEW_CUSTOMERS, COUNT( DISTINCT CASE WHEN CUSTOMER_TYPE = \'Repeat\' THEN CUSTOMER_ID END ) AS REPEAT_CUSTOMERS, COUNT(DISTINCT CUSTOMER_ID) AS TOTAL_CUSTOMERS FROM channel_customer_classification GROUP BY ORDER_MONTH_DATE, CHANNEL ), category_customer_classification AS ( SELECT ORDER_MONTH_DATE, CATEGORY, CUSTOMER_ID, CASE WHEN MAX( CASE WHEN CUSTOMER_TYPE = \'Repeat\' THEN 1 ELSE 0 END ) = 1 THEN \'Repeat\' ELSE \'New\' END AS CUSTOMER_TYPE FROM customer_base GROUP BY ORDER_MONTH_DATE, CATEGORY, CUSTOMER_ID ), category_level AS ( SELECT ORDER_MONTH_DATE, \'CATEGORY_LEVEL\' AS ANALYSIS_LEVEL, CATEGORY, \'ALL\' AS CHANNEL, COUNT( DISTINCT CASE WHEN CUSTOMER_TYPE = \'New\' THEN CUSTOMER_ID END ) AS NEW_CUSTOMERS, COUNT( DISTINCT CASE WHEN CUSTOMER_TYPE = \'Repeat\' THEN CUSTOMER_ID END ) AS REPEAT_CUSTOMERS, COUNT(DISTINCT CUSTOMER_ID) AS TOTAL_CUSTOMERS FROM category_customer_classification GROUP BY ORDER_MONTH_DATE, CATEGORY ), category_channel_level AS ( SELECT ORDER_MONTH_DATE, \'CATEGORY_CHANNEL_LEVEL\' AS ANALYSIS_LEVEL, CATEGORY, CHANNEL, COUNT( DISTINCT CASE WHEN CUSTOMER_TYPE = \'New\' THEN CUSTOMER_ID END ) AS NEW_CUSTOMERS, COUNT( DISTINCT CASE WHEN CUSTOMER_TYPE = \'Repeat\' THEN CUSTOMER_ID END ) AS REPEAT_CUSTOMERS, COUNT(DISTINCT CUSTOMER_ID) AS TOTAL_CUSTOMERS FROM customer_base GROUP BY ORDER_MONTH_DATE, CATEGORY, CHANNEL ), final_base AS ( SELECT ORDER_MONTH_DATE, ANALYSIS_LEVEL, CATEGORY, CHANNEL, NEW_CUSTOMERS, REPEAT_CUSTOMERS, TOTAL_CUSTOMERS FROM channel_level UNION ALL SELECT ORDER_MONTH_DATE, ANALYSIS_LEVEL, CATEGORY, CHANNEL, NEW_CUSTOMERS, REPEAT_CUSTOMERS, TOTAL_CUSTOMERS FROM category_level UNION ALL SELECT ORDER_MONTH_DATE, ANALYSIS_LEVEL, CATEGORY, CHANNEL, NEW_CUSTOMERS, REPEAT_CUSTOMERS, TOTAL_CUSTOMERS FROM category_channel_level ) SELECT ORDER_MONTH_DATE, TO_CHAR( ORDER_MONTH_DATE, \'MMMM YYYY\' ) AS ORDER_MONTH, ANALYSIS_LEVEL, CATEGORY, CHANNEL, NEW_CUSTOMERS, REPEAT_CUSTOMERS, TOTAL_CUSTOMERS, ROUND( NEW_CUSTOMERS * 100.0 / NULLIF(TOTAL_CUSTOMERS, 0), 2 ) AS NEW_CUSTOMER_PCT, ROUND( REPEAT_CUSTOMERS * 100.0 / NULLIF(TOTAL_CUSTOMERS, 0), 2 ) AS REPEAT_CUSTOMER_PCT FROM final_base ORDER BY ORDER_MONTH_DATE DESC, ANALYSIS_LEVEL, CATEGORY, CHANNEL;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            